    cursor: pointer;
  }
  #clear-completed:hover { color: var(--danger); text-decoration: underline; }
</style>
</head>
<body>
<main class="app">
  <h1>Todos</h1>

  <form id="todo-form" class="composer" autocomplete="off">
    <input id="new-todo" type="text" placeholder="What needs to be done?" maxlength="500" aria-label="New todo">
    <button id="add-btn" type="submit">Add</button>
  </form>

  <div class="filters" role="group" aria-label="Filter todos">
    <button type="button" data-filter="all" class="active">All</button>
    <button type="button" data-filter="active">Active</button>
    <button type="button" data-filter="completed">Completed</button>
  </div>

  <ul id="todo-list" aria-live="polite"></ul>

  <div class="footer">
    <span id="items-left"></span>
    <button id="clear-completed" type="button">Clear completed</button>
  </div>
</main>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'todos.v1';
  var todos = load();
  var currentFilter = 'all';

  var form = document.getElementById('todo-form');
  var input = document.getElementById('new-todo');
  var list = document.getElementById('todo-list');
  var itemsLeftEl = document.getElementById('items-left');
  var clearBtn = document.getElementById('clear-completed');
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filters button'));

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) { /* storage unavailable — app still works in-memory */ }
  }

  function addTodo(text) {
    todos.push({
      id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
      text: text,
      completed: false
    });
    save();
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    save();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function visibleTodos() {
    if (currentFilter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (currentFilter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function render() {
    list.innerHTML = '';
    var items = visibleTodos();

    if (items.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty-state';
      empty.textContent = currentFilter === 'active' ? 'Nothing active — add a todo!'
        : currentFilter === 'completed' ? 'No completed todos yet.'
        : 'No todos yet — add one above.';
      list.appendChild(empty);
    } else {
      items.forEach(function (todo) {
        var li = document.createElement('li');

        var checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.className = 'todo-checkbox';
        checkbox.checked = todo.completed;
        checkbox.setAttribute('aria-label', 'Toggle: ' + todo.text);
        checkbox.addEventListener('change', function () { toggleTodo(todo.id); });

        var span = document.createElement('span');
        span.className = 'todo-text' + (todo.completed ? ' completed' : '');
        span.textContent = todo.text;
        span.addEventListener('click', function () { toggleTodo(todo.id); });

        var del = document.createElement('button');
        del.type = 'button';
        del.className = 'delete-btn';
        del.textContent = '\u00d7';
        del.setAttribute('aria-label', 'Delete: ' + todo.text);
        del.addEventListener('click', function () { deleteTodo(todo.id); });

        li.appendChild(checkbox);
        li.appendChild(span);
        li.appendChild(del);
        list.appendChild(li);
      });
    }

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    itemsLeftEl.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');
    clearBtn.style.visibility = todos.some(function (t) { return t.completed; }) ? 'visible' : 'hidden';
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    addTodo(text);
    input.value = '';
    input.focus();
  });

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      currentFilter = btn.getAttribute('data-filter');
      filterBtns.forEach(function (b) { b.classList.toggle('active', b === btn); });
      render();
    });
  });

  clearBtn.addEventListener('click', clearCompleted);

  render();
})();
</script>
</body>
</html>
